struct Node;

/// Largest instant representable as a four-digit year: 9999-12-31T23:59:59Z.
const MAX_SECONDS: i64 = 253_402_300_799;

/// Format Unix seconds as a `YYYY-MM-DD` UTC date. Always exactly 10 bytes:
/// the input is clamped to year 9999 so the four-digit year never overflows.
fn format_utc_date(unix_seconds: u64) -> String {
    let secs = (unix_seconds.min(MAX_SECONDS as u64)) as i64;
    let z = secs.div_euclid(86_400) + 719_468;

    // Civil-from-days (Howard Hinnant's algorithm), proleptic Gregorian calendar.
    let era = z.div_euclid(146_097);
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let mut year = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let day = doy - (153 * mp + 2) / 5 + 1;
    let month = if mp < 10 { mp + 3 } else { mp - 9 };
    if month <= 2 {
        year += 1;
    }

    format!("{:04}-{:02}-{:02}", year, month, day)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wasi::clocks::wall_clock::now();
        let started = now.seconds;
        RunInfo {
            date: format_utc_date(started),
            started,
        }
    }
}

export!(Node);
